window.StrictDoc.search.nodesByMid = {"1":{"MID":"ae9bcf62c86b4676a743ceacff128f8b","TITLE":"Functional Requirements","_LINK":"1-Functional-Requirements"},"2":{"MID":"60a62bb5194d4c64ae617280dcd56fc2","UID":"REQ-1","TITLE":"Resumable","STATEMENT":"The interpreter shall be resumable\n","RATIONALE":"Operation with fuel or other implementations of bounded run-time requires that the interpreter can be halted.\nConversely, later on the interpreter may be resumed, as if it was not halted in the first place.\n","_LINK":"REQ-1"},"3":{"MID":"eba7a0672288415196c00c6b86fe7f06","UID":"REQ-3","TITLE":"Baremetal","STATEMENT":"The interpreter shall be executable on bare-metal environments\n","RATIONALE":"No reliance on any specific functionality from the provided execution environment is acceptable, as the interpreter shall be ready for embedding to any environment that Rust can compile for.\n","_LINK":"REQ-3"},"4":{"MID":"90c902a3663f484cacec92b373eb4fdf","UID":"REQ-5","TITLE":"Bounded execution","STATEMENT":"The interpreter shall yield back control flow eventually\n","RATIONALE":"A user shall be able to call the interpreter with a bound, expecting a result in a finite amount of time or bytecode operations. Even if the bytecode itself does never finish execution (i.e. due to a infinite loop), the interpreter shall yield eventually, by pausing the bytecode execution.\n","COMMENT":"It is not acceptable to constraint the interpreter to only those bytecode instances for which the halting-problem is solvable.\n","_LINK":"REQ-5"},"5":{"MID":"9efbcb71e27b4a40b7ca74eb7c5c0355","UID":"REQ-12","TITLE":"Migrateable","STATEMENT":"The interpreter state shall be able to halt on one computer and continue execution on another\n","RATIONALE":"This enables various workflows in deployments of multiple computers. For load-balancing or redundancy purposes, running applications can be migrated to other computers without disruption.\n","_LINK":"REQ-12"},"6":{"MID":"3957ae743709454288bebaee4193633d","UID":"REQ-14","TITLE":"No Dependencies","STATEMENT":"No dependencies but those explicitly allowed by a requirement shall be used\n","RATIONALE":"Dependencies have to forego the full V&V process as well, which quickly adds enormous work.\n","COMMENT":"This requirement constraints the usage and introduction of normal dependencies, but not Dev Dependencies [#]_ and not Build Dependencies [#]_ .\n\n.. [#] https://doc.rust-lang.org/cargo/reference/specifying-dependencies.html#development-dependencies\n.. [#] https://doc.rust-lang.org/cargo/reference/specifying-dependencies.html#build-dependencies\n","_LINK":"REQ-14"},"7":{"MID":"afda1aaf980b4fecb90dbba3048be462","UID":"REQ-18","TITLE":"Standard Compliance","STATEMENT":"The interpreter shall be compliant with version 2.0, 16 June 2025, of the core WebAssembly standard (https://www.w3.org/TR/2025/CRD-wasm-core-2-20250616/).\n","RATIONALE":"Correct execution of web assembly code requires that the interpreter adheres to the standard.\n","COMMENT":"The chosen version is the most recent Candidate Recommendation Draft, which is considered the current standard as per https://webassembly.org/news/2025-03-20-wasm-2.0/.\n","_LINK":"REQ-18"},"8":{"MID":"5f9c475a27e74d1eba86d5ca2eb69e7d","TITLE":"Low-Level Functional Requirements","_LINK":"1.7-Low-Level-Functional-Requirements"},"9":{"MID":"8c1f9aa62a354991b29d2fe8c4f2f6ac","UID":"REQ-2","TITLE":"Stackless","STATEMENT":"The interpreter shall be stackless\n","RATIONALE":"A stackless interpreter is one that does not use function calls in the host environment to implement function calls inside the interpreter. Instead, the stack of the interpreted bytecode is stored in a traditional data structure (such as a Vec<u8>). Interpretation can be interrupted between any two virtual instructions of the bytecode, and crucially so resumed from there.\n\nFurther information: https://kyju.org/blog/piccolo-a-stackless-lua-interpreter/#a-stackless-interpreter-design\n","_LINK":"REQ-2"},"10":{"MID":"8e08156bdd62400a801bb96ed84f025f","UID":"REQ-4","TITLE":"no_std","STATEMENT":"The interpreter shall be implemented in no_std Rust\n","RATIONALE":"Only relying on the functionality that is provided by no_std enables execution on bare environments where operating system is available.\n","COMMENT":"Reliance on alloc is allowable, as an allocator can be implemented without further reliance on the execution environment.\n","_LINK":"REQ-4"},"11":{"MID":"b9d27a1e451445dda94253b79d48c205","UID":"REQ-6","TITLE":"Fuel","STATEMENT":"The interpreter shall support fuel bounded execution\n","RATIONALE":"Fuel is a mechanism to limit the amount of bytecode operations conducted when calling the interpreter. Each bytecode instruction is associated with a specific amount of fuel consumed when executing it. The interpreter is provided a finite amount of fuel, that is deplete during execution, until the amount of fuel is insufficient to conduct further bytecode operations. At this point, the interpreter yields back the control flow. Later on, the execution may be resumed.\n\nFurther information: https://docs.rs/wasmtime/latest/wasmtime/struct.Config.html#method.consume_fuel\n","_LINK":"REQ-6"},"12":{"MID":"eb84baeb1a7048c59b36ebabf9210f5a","UID":"REQ-13","TITLE":"De-/Serializable","STATEMENT":"The interpreter state shall be de-/serializable\n","RATIONALE":"If the interpreter state can be serialized to and deserialized from a canonical representation, migration to other computers as well as check-point/lock-step like execution become simple to implement.\n","_LINK":"REQ-13"},"13":{"MID":"edc4dea818654728abed476ea73a60ff","UID":"REQ-15","STATUS":"Deleted","TITLE":"Allow log dependency","STATEMENT":"The interpreter shall have an optional dependency on the ``log`` version ``0.4.22`` or later.\n","RATIONALE":"Logging is an essential tool to make a system observable, and aid in debugging. Bespoke crate is widely used in the Rust ecosystem and can be attached to any (or no) logging backend. Using conditional compilation, all of the ``log`` crate's footprint in the WASM interpreter (foremost the ``debug``, ``error``, ``info``, ``trace`` and ``warn`` macro) can be expanded to empty statements to avoid **any** run-time impact when opting out of the dependency on ``log``.\n","COMMENT":"This requirement was marked as deleted on 2026-08-03 because the advantages of logging as a feature do not outweigh its disadvantages (e.g. coverage gaps and excess string formatting code).\n","_LINK":"REQ-15"},"14":{"MID":"752c71889deb41efad6487038a95f805","UID":"REQ-16","TITLE":"Allow libm dependency","STATEMENT":"The interpreter may depend on the ``libm`` crate version ``0.2.8`` or later.\n","RATIONALE":"Rust does not expose all floating point operations in a bare-metal (as in ``no_std``) target, as to not introduce any dependency on the C standard library's ``libm`` (respective PR: https://github.com/rust-lang/rust/pull/27823). However, we identified at least the following operations to be required for WASM interpretation while unavailable in ``no_std``:\n\n- ``abs``\n- ``ceil``\n- ``floor``\n- ``trunc``\n- ``round``\n- ``sqrt``\n- ``copysign``\n\nIn order use these operations, having the ``libm`` crate as dependencies of the WASM interpreter is an acceptable trade-off.\n","_LINK":"REQ-16"},"15":{"MID":"b0a97780b82f43679d967cea5406bd7f","UID":"REQ-17","TITLE":"Minimum Supported Rust Version (MSRV)","STATEMENT":"The interpreter shall compile on Rust ``1.87.0`` and later versions\n","RATIONALE":"An MSRV should be clearly stated to specify which toolchain is acceptable.\n","_LINK":"REQ-17"},"16":{"MID":"1fcc544d2d174d08ad5b9d7ef7578265","TITLE":"Observability Requirements","_LINK":"2-Observability-Requirements"},"17":{"MID":"ea0e2c7c00bb4c0fb54fd66843eb0435","UID":"REQ-7","TITLE":"Instrumentation","STATEMENT":"The interpreter shall implement means for instrumentation\n","RATIONALE":"Instrumentation is needed to generate evidence for certification. Instrumentation eases debugging. Instrumentation enables elaborate run-time monitoring.\n","_LINK":"REQ-7"},"18":{"MID":"5f083da3f77444ad9cf5762f38adb44c","TITLE":"Low-Level Observability Requirements","_LINK":"2.2-Low-Level-Observability-Requirements"},"19":{"MID":"a817d1c9f0a5450abdcbfbc88295b4e9","UID":"REQ-8","TITLE":"Statement Coverage","STATEMENT":"The instrumentation shall enable the measurement of statement coverage\n","RATIONALE":"Statement coverage is required by DO-178C starting at DAL-C (6.4.4.c)\n","_LINK":"REQ-8"},"20":{"MID":"86ad5615722d48dda7bb5dfe3b52be7e","UID":"REQ-9","TITLE":"Decision Coverage","STATEMENT":"The instrumentation shall enable the measurement of decision coverage\n","RATIONALE":"Decision coverage is required by DO-178C starting at DAL-B (6.4.4.c)\n","_LINK":"REQ-9"},"21":{"MID":"b4682df938914ce98a894f20b493bf04","UID":"REQ-10","TITLE":"Modified Condition/Decision Coverage","STATEMENT":"The instrumentation shall enable the measurement of modified condition/decision coverage\n","RATIONALE":"Modified condition/decision coverage is required by DO-178C starting at DAL-A (6.4.4.c)\n","_LINK":"REQ-10"},"22":{"MID":"de97b2566332425e8af7271b8f0ce3b7","UID":"REQ-11","TITLE":"Certification Evidence","STATEMENT":"The interpreter shall support the generation of certification evidence\n","_LINK":"REQ-11"}};
